/** Actual registered source/day/lineage/native P2 archives; already-applied model genesis remains fictional. */
@EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class NewsDayReportComponentMySqlTest extends NewsDayReportComponentTest {
    @Override GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreMySqlTest();}
    SourceDayPipelineIntegrationMySqlTest pipeline;NewsDayReportComponentService nativeService;
    void nativeSetup(boolean partial)throws Exception{pipeline=new SourceDayPipelineIntegrationMySqlTest();pipeline.setup(partial);var day=pipeline.day;var db=pipeline.f.db;var graph=day.graph;var completions=new SourceValueReportCompletionService(graph.plans(),graph.valueProofs(),graph.finalization(),graph.finalObserver(),day.manager);var source=new NewsSourceReportComponentService(completions,new NewsReportLeafEvidenceService(new JdbcNewsReportLeaves(db.source)),day.manager);var registered=new SourceDayRunClaimAdmissionConfiguration().create(db.source,day.manager,new SourceDayCollectionAdmissionService(day.cohorts));nativeService=new NewsDayReportComponentService(day.cohorts,day.barriers,new JdbcSourceDayDedupClosures(db.source),registered,graph.plans(),graph.dedupProofs(),graph.dedupObserver(),graph.handoffReceipts(),day.permits,completions,source,day.manager);}
    Instant cutoff(){return pipeline.f.clock.instant();}
    NewsDayReportComponentService.Captured nativeCapture(){return nativeService.capture(pipeline.day.day,cutoff());}
    <T>T nativeRr(java.util.function.Supplier<T> work){var tx=new TransactionTemplate(pipeline.day.manager);tx.setReadOnly(true);tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->work.get());}
    @Test void ActualRegisteredOriginalSourceWithoutHandoffIsMissingNeverSuccessfulEmpty()throws Exception{nativeSetup(false);pipeline.day.barriers.close(pipeline.day.day);var value=nativeCapture();assertNotNull(value);assertFalse(value.completeSuccessfulEmpty());assertEquals("value_handoff_unproven",value.missing().getFirst().reason());assertSame(value,nativeRr(()->nativeService.verifyObserved(value)));pipeline.f.db.jdbc.execute("DROP TABLE sources");assertEquals(value.missing(),nativeCapture().missing());}
    @Test void ActualOriginalP2PlanBeforeCompletionIsExplicitPendingAndBecomingCompleteRejectsOldCapture()throws Exception{nativeSetup(true);String owner=pipeline.child();assertEquals(SourceAnalysisParentStepService.Status.PREPARED,pipeline.parent.step(pipeline.f.candidate(owner)).status());var value=nativeCapture();assertEquals("value_not_completed_at_cutoff",value.missing().getFirst().reason());assertFalse(value.completeSuccessfulEmpty());assertEquals(SourceAnalysisParentStepService.Status.FINALIZED,pipeline.parent.step(pipeline.f.candidate(owner)).status());assertThrows(RuntimeException.class,()->nativeRr(()->nativeService.verifyObserved(value)));var fresh=nativeCapture();assertTrue(fresh.candidates().isEmpty());assertFalse(fresh.missing().isEmpty());assertFalse(fresh.completeSuccessfulEmpty());assertSame(fresh,nativeRr(()->nativeService.verifyObserved(fresh)));}
    @Test void NativeRegistrationOrOriginalP1DamageCannotReuseWholeDay()throws Exception{nativeSetup(false);pipeline.day.barriers.close(pipeline.day.day);var value=nativeCapture();pipeline.f.db.jdbc.update("DELETE FROM request_receipts WHERE actor_id='source-day-register'");assertThrows(RuntimeException.class,()->nativeRr(()->nativeService.verifyObserved(value)));assertThrows(RuntimeException.class,this::nativeCapture);}
    @Test void ActualOriginalCompletedSourceAndNativeArticleRevisionFormCompleteNewsDay()throws Exception{
        nativeSetup(false);pipeline.projectFictionalAppliedMember();String owner=pipeline.child();var prepared=pipeline.preparation.prepareValue(owner,pipeline.day.run(),pipeline.day.original.ref,0);var ref=pipeline.f.reference(owner);pipeline.f.completeP2(ref);pipeline.day.graph.finalization().finish(ref);pipeline.day.graph.finalObserver().capture(ref);nativeLeaves(ref);
        var value=nativeCapture();assertNotNull(value);assertFalse(value.candidates().isEmpty());assertTrue(value.missing().isEmpty());assertEquals(value.candidates().size(),value.referenceTargetsByEvidence().size());assertSame(value,nativeRr(()->nativeService.verifyObserved(value)));String body=value.candidates().getFirst().evidence().bodyJson();pipeline.f.db.jdbc.update("UPDATE sources SET activation_stage='disabled',state='disabled',config_revision=config_revision+1");assertEquals(body,nativeCapture().candidates().getFirst().evidence().bodyJson());pipeline.f.db.jdbc.update("UPDATE article_revisions SET effective_valid=0,validity_revision=validity_revision+1");assertThrows(RuntimeException.class,()->nativeRr(()->nativeService.verifyObserved(value)));assertFalse(nativeCapture().candidates().getFirst().evidence().effectiveValid());
    }
    void nativeLeaves(FrozenSourceStagePlan.Reference ref)throws Exception{
        var db=pipeline.f.db;for(String column:List.of("article_id","article_revision_id")){try(var connection=db.source.getConnection();var rows=connection.getMetaData().getColumns(connection.getCatalog(),null,"source_run_items",column)){if(!rows.next())db.jdbc.execute("ALTER TABLE source_run_items ADD "+column+" VARCHAR(64)");}}
        db.jdbc.execute("DROP TABLE IF EXISTS article_revisions");db.jdbc.execute("CREATE TABLE article_revisions(id VARCHAR(64) PRIMARY KEY,article_id VARCHAR(64),title VARCHAR(512),source_summary MEDIUMTEXT,body_text MEDIUMTEXT,content_hash BINARY(32),created_at DATETIME(6),legacy_flag INT,effective_valid INT,validity_revision BIGINT)");
        var plan=nativeRr(()->pipeline.day.graph.plans().readImmutable(ref));var recorded=LocalDateTime.ofInstant(cutoff().minusSeconds(1),ZoneOffset.UTC);
        for(var chunk:plan.chunks()){var snapshot=CanonicalJson.parse(chunk.snapshotJson());var context=FrozenApplicationContext.fromJson(snapshot.get(FrozenApplicationContext.FIELD));var bindings=FrozenMemberBindings.read(snapshot,context.input(chunk.rootId(),"fictional-news-leaf-association",chunk.inputHash(),0));for(var member:snapshot.get("members")){String id=member.get("id").asText(),article="fictional-article-"+id,revision="fictional-revision-"+id;var payload=member.get("body");var projected=JsonMapper.shared().createObjectNode();projected.set("title",payload.get("title"));projected.set("summary",payload.get("source_summary"));projected.set("body_text",payload.get("body_text"));db.jdbc.update("UPDATE source_run_items SET article_id=?,article_revision_id=?,revision=?,state='ready',evidence_json=?,evidence_hash=?,created_at=? WHERE id=?",article,revision,bindings.get(id).expectedRevision()+2,JdbcFrozenInputs.canonical(payload),java.security.MessageDigest.getInstance("SHA-256").digest(CanonicalJson.bytes(payload)),recorded,id);db.jdbc.update("INSERT INTO article_revisions VALUES(?,?,?,?,?,?,?,0,1,0)",revision,article,payload.get("title").asText(),payload.get("source_summary").isNull()?null:payload.get("source_summary").asText(),payload.get("body_text").isNull()?null:payload.get("body_text").asText(),HexFormat.of().parseHex(CanonicalJson.hash(CanonicalJson.Domain.ARTICLE_PROJECTION,projected)),recorded);}}
    }
}
